    """Total price of a hotel stay."""
    if night_count < 1:
        raise ValueError('stay must be at least one night')
    if guest_count < 1:
        raise ValueError('at least one guest is required')
    if guest_count <= 4:
        if season == 'high':
            nightly = 210
        elif season == 'shoulder':
            nightly = 150
        else:
            nightly = 95
        if guest_count > 2:
            nightly = nightly + (guest_count - 2) * 25
        total = nightly * night_count
        if night_count >= 7:
            total = total * 0.9
        return round(total, 2)
    else:
        raise ValueError('at least one guest is required')
